export default function () {
  const [arr, setArr] = useImmer([1,2])
  const [test, setTest] = useState([2,2])
  function Change() {
    setArr(draft => {
      draft[0] = draft[0]+1
    })
  }
  function Test() {
    setTest(e => e.join(" "))
  }
  return (
    <>
    <button onClick={Change}>click</button> <br/>
    <button onClick={Test}>click</button> <br/>
    {test} <br/>
    {arr.join(" ")} 
    </>
  );
}
